import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.doxMM-x8.js";const g=JSON.parse('{"title":"Appearance And Language","description":"","frontmatter":{"docLocale":"en","counterpart":"/tutorials/appearance-language","contentType":"guide","prev":false,"next":false},"headers":[],"relativePath":"en/tutorials/appearance-language.md","filePath":"en/tutorials/appearance-language.md"}'),r={name:"en/tutorials/appearance-language.md"};function i(o,e,l,c,p,d){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="appearance-and-language" tabindex="-1">Appearance And Language <a class="header-anchor" href="#appearance-and-language" aria-label="Permalink to &quot;Appearance And Language&quot;">​</a></h1><p>Goal: switch Lab Word language and appearance and verify device preferences persist. Start the application with <a href="./../getting-started/quickstart">quick start</a>first.</p><h2 id="operation-and-result" tabindex="-1">Operation And Result <a class="header-anchor" href="#operation-and-result" aria-label="Permalink to &quot;Operation And Result&quot;">​</a></h2><ol><li>Use the topbar language action to choose Simplified Chinese or English. Interface text and page title should update together.</li><li>Choose system, light or dark appearance. System mode follows operating-system changes.</li><li>Open settings from the account entry at the lower left to change the same preferences.</li><li>Refresh and confirm explicit choices persist. Narrow screens expose the relevant entries through navigation.</li></ol><p>Preferences stay on this device and do not change permissions or business data. Browsers do not synchronize automatically. Disabled storage or cleared site data restores device defaults.</p><h2 id="development-and-validation" tabindex="-1">Development And Validation <a class="header-anchor" href="#development-and-validation" aria-label="Permalink to &quot;Development And Validation&quot;">​</a></h2><p><a href="https://github.com/CaiZongyuan/labworld/blob/5fe346857c30fec312a9aab1fa984f5d298dcd3b/packages/views/src/shell/preferences.tsx" target="_blank" rel="noreferrer">Preferences</a>owns state/storage and <a href="https://github.com/CaiZongyuan/labworld/blob/5fe346857c30fec312a9aab1fa984f5d298dcd3b/packages/views/src/shell/settings-view.tsx" target="_blank" rel="noreferrer">Settings</a>provides controls. <a href="https://github.com/CaiZongyuan/labworld/blob/5fe346857c30fec312a9aab1fa984f5d298dcd3b/packages/views/src/shell/core-messages.ts" target="_blank" rel="noreferrer">core-messages.ts</a>owns translations; shared tokens come from <code>packages/ui/src/styles.css</code>.</p><p>Run from the repository root:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> exec</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vitest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/settings.test.tsx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> apps/web/src/desktop-preferences.test.tsx</span></span></code></pre></div><p>Component checks observe choices and persistence. Verify the Electron bridge and real system appearance in their respective journeys. The documentation site has its own controls and preserves the current chapter across languages.</p><hr><p>Source version：<code>5fe346857c30</code> · <a href="https://github.com/CaiZongyuan/labworld/blob/5fe346857c30fec312a9aab1fa984f5d298dcd3b/docs/guides/appearance-language.en.md" target="_blank" rel="noreferrer">Page Markdown</a></p>',12)])])}const u=a(r,[["render",i]]);export{g as __pageData,u as default};
